### Task 1: Parcel Intake, Sorting and Processing Module

#### Data Structure Justification
To manage incoming parcels efficiently, a combination of a **Singly Linked List** (for master record maintenance) and a **FIFO Queue** (implemented via pointers for pending parcel intake) is used. The Queue ensures that parcels arriving at the campus delivery centre are processed in strict First-In-First-Out order based on arrival time, preventing bottlenecks during peak hours. The Linked List allows dynamic memory allocation to store all historical and active parcels without a fixed size limit.

#### C++ Implementation
```cpp
#include <iostream>
#include <string>
using namespace std;

struct Parcel {
    string parcelID, recipientID, recipientName, company, type, arrivalTime, status;
    Parcel* next;
};

class ParcelIntakeModule {
private:
    Parcel* head = nullptr;
    Parcel* qFront = nullptr;
    Parcel* qRear = nullptr;

public:
    bool exists(string id) {
        for (Parcel* cur = head; cur; cur = cur->next)
            if (cur->parcelID == id) return true;
        return false;
    }

    void registerParcel(string id, string rID, string rName, string comp, string type, string time) {
        if (id.empty() || rID.empty() || rName.empty()) {
            cout << "Error: Incomplete parcel information.\n"; return;
        }
        if (exists(id)) {
            cout << "Error: Duplicate Parcel ID " << id << ".\n"; return;
        }
        Parcel* np = new Parcel{id, rID, rName, comp, type, time, "Pending", head};
        head = np;
        Parcel* qp = new Parcel{*np};
        qp->next = nullptr;
        if (!qRear) qFront = qRear = qp;
        else { qRear->next = qp; qRear = qp; }
        cout << "Registered Parcel: " << id << " [Status: Pending]\n";
    }

    void processNextParcel() {
        if (!qFront) { cout << "Error: No pending parcels to process.\n"; return; }
        Parcel* temp = qFront;
        qFront = qFront->next;
        if (!qFront) qRear = nullptr;

        string nextStatus = "Ready for Collection";
        if (temp->type == "Fragile Parcel" || temp->type == "Special-Handling Parcel")
            nextStatus = "Processing (Special Handling)";
        else if (temp->type == "Large Parcel")
            nextStatus = "Out for Delivery";

        updateStatus(temp->parcelID, nextStatus);
        delete temp;
    }

    void updateStatus(string id, string newStatus) {
        for (Parcel* cur = head; cur; cur = cur->next) {
            if (cur->parcelID == id) {
                if (cur->status == "Collected" || cur->status == "Cancelled") {
                    cout << "Error: Cannot modify completed parcel " << id << ".\n"; return;
                }
                cur->status = newStatus;
                cout << "Parcel " << id << " updated to: " << newStatus << "\n";
                return;
            }
        }
        cout << "Error: Parcel " << id << " not found.\n";
    }

    void displayAll() {
        if (!head) { cout << "No parcels registered.\n"; return; }
        for (Parcel* cur = head; cur; cur = cur->next)
            cout << cur->parcelID << " | " << cur->recipientName << " | " << cur->type << " | " << cur->status << "\n";
    }
};
```

#### Expected Core Output Handling
- **Registration & Validation:** Checks for empty strings and traverses the list to reject duplicate IDs before inserting into both the master list and pending queue.
- **Sorting & Routing:** `processNextParcel()` dequeues the oldest pending parcel and automatically classifies its next stage based on `Parcel Type` (e.g., routing Fragile parcels to Special Handling and Standard parcels to Collection).
- **Exception Handling:** Prevents processing when `qFront == nullptr`, blocks status updates on already `Collected` or `Cancelled` parcels, and reports missing IDs during search.

### Task 2: Parcel Service and Collection Management Module

#### Data Structure & Processing Rule Justification
A **Priority Queue** (implemented as a sorted singly linked list) is selected to manage active service requests. 
**Justification of Rule:** Not all parcel services have equal urgency. We assign numeric priorities based on Service Type:
1. `Special Handling` (Priority 1 - Highest: often fragile/perishable)
2. `Re-delivery` (Priority 2 - Delayed items needing urgent resolution)
3. `Campus Delivery` (Priority 3 - Scheduled dispatch)
4. `Recipient Collection` (Priority 4 - Standard counter pickup)
5. `Return to Sender` (Priority 5 - Lowest urgency)

If two requests have equivalent priority, the sorted insertion preserves **First-Come-First-Served (FCFS)** order based on insertion sequence.

#### C++ Implementation
```cpp
#include <iostream>
#include <string>
using namespace std;

struct ServiceRequest {
    string reqID, parcelID, recID, recName, serviceType, reqTime, status;
    int priority;
    ServiceRequest* next;
};

class ServiceManagementModule {
private:
    ServiceRequest* activeHead = nullptr;
    ServiceRequest* historyHead = nullptr;

    int getPriority(string type) {
        if (type == "Special Handling") return 1;
        if (type == "Re-delivery") return 2;
        if (type == "Campus Delivery") return 3;
        if (type == "Recipient Collection") return 4;
        return 5;
    }

public:
    void createRequest(string rID, string pID, string recID, string rName, string sType, string time) {
        if (rID.empty() || pID.empty()) { cout << "Error: Invalid IDs.\n"; return; }
        for (ServiceRequest* c = activeHead; c; c = c->next)
            if (c->reqID == rID) { cout << "Error: Duplicate Request ID.\n"; return; }

        int prio = getPriority(sType);
        ServiceRequest* nr = new ServiceRequest{rID, pID, recID, rName, sType, time, "Pending", prio, nullptr};

        if (!activeHead || prio < activeHead->priority) {
            nr->next = activeHead;
            activeHead = nr;
        } else {
            ServiceRequest* cur = activeHead;
            while (cur->next && cur->next->priority <= prio) cur = cur->next;
            nr->next = cur->next;
            cur->next = nr;
        }
        cout << "Created Request " << rID << " (Priority " << prio << ")\n";
    }

    void processNextRequest(string outcomeStatus = "Completed") {
        if (!activeHead) { cout << "Error: No active requests.\n"; return; }
        ServiceRequest* target = activeHead;
        activeHead = activeHead->next;
        target->status = outcomeStatus;
        target->next = historyHead;
        historyHead = target;
        cout << "Processed Request " << target->reqID << " for Parcel " << target->parcelID 
             << " -> Status: " << target->status << "\n";
    }

    void cancelRequest(string rID) {
        ServiceRequest *cur = activeHead, *prev = nullptr;
        while (cur && cur->reqID != rID) { prev = cur; cur = cur->next; }
        if (!cur) { cout << "Error: Active request " << rID << " not found or already completed.\n"; return; }
        if (!prev) activeHead = cur->next;
        else prev->next = cur->next;
        cur->status = "Cancelled";
        cur->next = historyHead;
        historyHead = cur;
        cout << "Request " << rID << " cancelled.\n";
    }

    void displayActive() {
        if (!activeHead) { cout << "No active requests.\n"; return; }
        for (ServiceRequest* c = activeHead; c; c = c->next)
            cout << "[P" << c->priority << "] " << c->reqID << " | Parcel: " << c->parcelID << " | " << c->serviceType << "\n";
    }
};
```

#### Exceptional Conditions Handled
- **Equivalent Processing Conditions:** Handled via `cur->next->priority <= prio` which places newer requests of the same priority behind existing ones.
- **Invalid/Completed Operations:** Completed or cancelled requests are immediately moved from `activeHead` to `historyHead`, making it impossible to process them twice.

### Task 5: Parcel Category Organisation Module

#### Organization Key & Traversal Justification
- **Selected Organization Key:** `Parcel ID` (Unique alphanumeric key, e.g., `P1001`). A **Binary Search Tree (BST)** is implemented using `Parcel ID` as the key because each parcel requires fast $O(\log n)$ average-case lookup, insertion, and deletion while preventing duplicate records.
- **Selected Traversal Method:** **In-Order Traversal (Left, Root, Right)**. This method is chosen because it visits nodes in ascending lexicographical order of `Parcel ID`, producing a clean, sorted manifest for campus staff audits.

#### C++ Implementation
```cpp
#include <iostream>
#include <string>
using namespace std;

struct TreeNode {
    string parcelID, recipientName, category, serviceType, status;
    TreeNode *left = nullptr, *right = nullptr;
};

class ParcelBST {
private:
    TreeNode* root = nullptr;

    TreeNode* insert(TreeNode* node, string id, string name, string cat, string srv, string st) {
        if (!node) return new TreeNode{id, name, cat, srv, st};
        if (id < node->parcelID) node->left = insert(node->left, id, name, cat, srv, st);
        else if (id > node->parcelID) node->right = insert(node->right, id, name, cat, srv, st);
        else cout << "Error: Duplicate Parcel Key " << id << " rejected.\n";
        return node;
    }

    TreeNode* search(TreeNode* node, string id) {
        if (!node || node->parcelID == id) return node;
        return (id < node->parcelID) ? search(node->left, id) : search(node->right, id);
    }

    void inOrder(TreeNode* node) {
        if (!node) return;
        inOrder(node->left);
        cout << node->parcelID << " | " << node->recipientName << " | " << node->category << " | " << node->status << "\n";
        inOrder(node->right);
    }

    TreeNode* findMin(TreeNode* node) {
        while (node && node->left) node = node->left;
        return node;
    }

    TreeNode* remove(TreeNode* node, string id, bool &deleted) {
        if (!node) return nullptr;
        if (id < node->parcelID) node->left = remove(node->left, id, deleted);
        else if (id > node->parcelID) node->right = remove(node->right, id, deleted);
        else {
            deleted = true;
            if (!node->left) { TreeNode* r = node->right; delete node; return r; }
            if (!node->right) { TreeNode* l = node->left; delete node; return l; }
            TreeNode* succ = findMin(node->right);
            node->parcelID = succ->parcelID; node->recipientName = succ->recipientName;
            node->category = succ->category; node->serviceType = succ->serviceType; node->status = succ->status;
            node->right = remove(node->right, succ->parcelID, deleted);
        }
        return node;
    }

public:
    void addParcel(string id, string name, string cat, string srv, string st) {
        if (id.empty() || name.empty()) { cout << "Error: Invalid parcel data.\n"; return; }
        root = insert(root, id, name, cat, srv, st);
    }

    void findParcel(string id) {
        TreeNode* res = search(root, id);
        if (!res) cout << "Parcel " << id << " not found in tree.\n";
        else cout << "Found: " << res->parcelID << " (" << res->category << ") - " << res->status << "\n";
    }

    void updateStatus(string id, string newStatus) {
        TreeNode* res = search(root, id);
        if (!res) cout << "Error: Cannot update non-existent parcel " << id << ".\n";
        else { res->status = newStatus; cout << "Updated " << id << " status to " << newStatus << ".\n"; }
    }

    void deleteParcel(string id) {
        bool deleted = false;
        root = remove(root, id, deleted);
        cout << (deleted ? "Deleted " + id + " successfully.\n" : "Error: Parcel " + id + " not found.\n");
    }

    void displayAll() {
        if (!root) { cout << "Tree is empty.\n"; return; }
        inOrder(root);
    }
};
```

#### Handling Structural Exceptions
- **Structural Integrity on Deletion:** When removing a node with two children, the algorithm locates the in-order successor (`findMin(node->right)`), copies its data, and recursively deletes the successor, preserving BST properties.
- **Edge Cases:** Empty trees (`root == nullptr`), non-existent keys during search/update/delete, and duplicate keys are explicitly trapped with user feedback.
